import time
import threading
import hashlib
import os
from functools import wraps
from dataclasses import dataclass, field
from typing import Dict, Optional, Set, Tuple


# Password hashing helpers using salted PBKDF2-HMAC-SHA256
_PBKDF2_ITERATIONS = 200_000
_SALT_BYTES = 16


def hash_password(password: str) -> str:
    """Hash a password with a random salt using PBKDF2-HMAC-SHA256."""
    salt = os.urandom(_SALT_BYTES)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, _PBKDF2_ITERATIONS)
    return f"pbkdf2_sha256${_PBKDF2_ITERATIONS}${salt.hex()}${dk.hex()}"


def verify_password(password: str, stored: str) -> bool:
    """Verify a password against a stored PBKDF2 hash in constant time."""
    try:
        algorithm, iterations, salt_hex, hash_hex = stored.split('$')
        if algorithm != 'pbkdf2_sha256':
            return False
        iterations = int(iterations)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(hash_hex)
    except (ValueError, AttributeError):
        return False
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iterations)
    return hashlib.compare_digest(dk, expected)


# Thread-safe permission cache with TTL
class PermissionCache:
    def __init__(self, ttl_seconds: int = 30):
        self._cache: Dict[str, Tuple[Set[str], float]] = {}
        self._lock = threading.RLock()
        self._ttl = ttl_seconds
        self._invalidation_log: Dict[str, float] = {}

    def get(self, user_id: str) -> Optional[Set[str]]:
        with self._lock:
            if user_id in self._cache:
                permissions, cached_at = self._cache[user_id]
                # Check if cache entry is still valid
                if time.time() - cached_at < self._ttl:
                    # Check if there's been an invalidation AFTER this was cached
                    if user_id in self._invalidation_log:
                        invalidated_at = self._invalidation_log[user_id]
                        # Correct: if invalidation happened at or after caching,
                        # treat cache as stale (force fresh lookup)
                        if cached_at > invalidated_at:
                            return permissions
                        else:
                            # Invalidation happened at same time or after caching
                            del self._cache[user_id]
                            return None
                    return permissions
                else:
                    del self._cache[user_id]
                    return None
            return None

    def put(self, user_id: str, permissions: Set[str]):
        with self._lock:
            self._cache[user_id] = (permissions.copy(), time.time())

    def invalidate(self, user_id: str):
        with self._lock:
            self._invalidation_log[user_id] = time.time()
            # Note: we don't delete from _cache here; we rely on the
            # timestamp comparison in get() for consistency


@dataclass
class User:
    user_id: str
    username: str
    password_hash: str
    permissions: Set[str] = field(default_factory=set)
    is_active: bool = True


class UserStore:
    def __init__(self):
        self._users: Dict[str, User] = {}
        self._lock = threading.RLock()
        self._setup_demo_users()

    def _setup_demo_users(self):
        # Demo users for testing
        self._users['user_001'] = User(
            user_id='user_001',
            username='alice',
            password_hash=hash_password('demo_password_1'),
            permissions={'read:documents', 'write:documents', 'admin:users'},
            is_active=True
        )
        self._users['user_002'] = User(
            user_id='user_002',
            username='bob',
            password_hash=hash_password('demo_password_2'),
            permissions={'read:documents'},
            is_active=True
        )

    def get_permissions(self, user_id: str) -> Optional[Set[str]]:
        with self._lock:
            user = self._users.get(user_id)
            if user and user.is_active:
                return user.permissions.copy()
            return None

    def revoke_permission(self, user_id: str, permission: str) -> bool:
        with self._lock:
            user = self._users.get(user_id)
            if user:
                user.permissions.discard(permission)
                return True
            return False

    def deactivate_user(self, user_id: str) -> bool:
        with self._lock:
            user = self._users.get(user_id)
            if user:
                user.is_active = False
                user.permissions = set()
                return True
            return False


class AuthorizationService:
    def __init__(self):
        self.cache = PermissionCache(ttl_seconds=30)
        self.store = UserStore()
        self._audit_log = []
        self._audit_lock = threading.Lock()

    def check_permission(self, user_id: str, required_permission: str) -> bool:
        """Check if user has the required permission."""
        # First, try the cache
        cached_perms = self.cache.get(user_id)
        if cached_perms is not None:
            has_perm = required_permission in cached_perms
            self._log_access(user_id, required_permission, has_perm, 'cache')
            return has_perm

        # Cache miss - fetch from store
        perms = self.store.get_permissions(user_id)
        if perms is None:
            self._log_access(user_id, required_permission, False, 'store_miss')
            return False

        # Populate cache
        self.cache.put(user_id, perms)
        has_perm = required_permission in perms
        self._log_access(user_id, required_permission, has_perm, 'store')
        return has_perm

    def revoke_permission(self, admin_id: str, target_user_id: str, permission: str) -> dict:
        """Admin revokes a permission from a user."""
        # Verify admin has permission to manage users
        if not self.check_permission(admin_id, 'admin:users'):
            return {'success': False, 'error': 'Unauthorized'}

        # Revoke in store
        success = self.store.revoke_permission(target_user_id, permission)
        if success:
            # Invalidate cache for the target user
            self.cache.invalidate(target_user_id)
            self._log_access(target_user_id, permission, False, 'revoked')
            return {'success': True}
        return {'success': False, 'error': 'User not found'}

    def deactivate_user(self, admin_id: str, target_user_id: str) -> dict:
        """Admin deactivates a user entirely."""
        if not self.check_permission(admin_id, 'admin:users'):
            return {'success': False, 'error': 'Unauthorized'}

        success = self.store.deactivate_user(target_user_id)
        if success:
            self.cache.invalidate(target_user_id)
            return {'success': True, 'message': f'User {target_user_id} deactivated'}
        return {'success': False, 'error': 'User not found'}

    def _log_access(self, user_id: str, permission: str, granted: bool, source: str):
        with self._audit_lock:
            self._audit_log.append({
                'timestamp': time.time(),
                'user_id': user_id,
                'permission': permission,
                'granted': granted,
                'source': source
            })


# HTTP-like request handler simulation
class DocumentService:
    def __init__(self, auth_service: AuthorizationService):
        self.auth = auth_service
        self._documents = {
            'doc_001': {'title': 'Q4 Financial Report', 'content': 'Revenue: $2.3M', 'classification': 'confidential'},
            'doc_002': {'title': 'Team Roster', 'content': 'Alice, Bob, Charlie', 'classification': 'internal'},
        }

    def read_document(self, user_id: str, doc_id: str) -> dict:
        if not self.auth.check_permission(user_id, 'read:documents'):
            return {'status': 403, 'error': 'Access denied'}

        doc = self._documents.get(doc_id)
        if not doc:
            return {'status': 404, 'error': 'Document not found'}
        return {'status': 200, 'data': doc}

    def write_document(self, user_id: str, doc_id: str, content: str) -> dict:
        if not self.auth.check_permission(user_id, 'write:documents'):
            return {'status': 403, 'error': 'Access denied'}

        if doc_id not in self._documents:
            return {'status': 404, 'error': 'Document not found'}

        self._documents[doc_id]['content'] = content
        return {'status': 200, 'message': 'Document updated'}

    def list_users(self, admin_id: str) -> dict:
        if not self.auth.check_permission(admin_id, 'admin:users'):
            return {'status': 403, 'error': 'Access denied'}
        users = []
        for uid, user in self.auth.store._users.items():
            users.append({'user_id': uid, 'username': user.username, 'active': user.is_active})
        return {'status': 200, 'data': users}


def create_application():
    auth = AuthorizationService()
    docs = DocumentService(auth)
    return auth, docs
